package ai.ultron.mobile;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import android.speech.*;import android.speech.tts.TextToSpeech;import java.util.*;
public class MainActivity extends Activity {
 android.content.SharedPreferences prefs; TextView status; TextToSpeech tts; boolean ready=false;
 public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("ultron",0); LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setGravity(Gravity.CENTER);root.setBackgroundColor(Color.BLACK); TextView title=new TextView(this);title.setText("U L T R O N");title.setTextColor(Color.RED);title.setTextSize(30);root.addView(title);View orb=new View(this){protected void onDraw(Canvas c){super.onDraw(c);float x=getWidth()/2f,y=getHeight()/2f,r=Math.min(x,y)*.8f;Paint p=new Paint(3);p.setShader(new RadialGradient(x,y,r,new int[]{Color.WHITE,Color.RED,0xff350000,Color.BLACK},null,Shader.TileMode.CLAMP));c.drawCircle(x,y,r,p);}};root.addView(orb,new LinearLayout.LayoutParams(-1,0,1));status=new TextView(this);status.setText("Tap to speak");status.setTextColor(Color.WHITE);root.addView(status);Button mic=new Button(this);mic.setText("Speak to ULTRON");root.addView(mic);mic.setOnClickListener(v->{Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);try{startActivityForResult(i,1);}catch(Exception e){status.setText("Speech recognition unavailable");}});Button settings=new Button(this);settings.setText("AI Settings");root.addView(settings);settings.setOnClickListener(v->{EditText key=new EditText(this);key.setHint("Gemini API key");key.setInputType(129);key.setText(prefs.getString("key",""));new AlertDialog.Builder(this).setTitle("Gemini connection").setView(key).setPositiveButton("Save",(d,w)->prefs.edit().putString("key",key.getText().toString().trim()).apply()).setNegativeButton("Cancel",null).show();});setContentView(root);tts=new TextToSpeech(this,s->{ready=s==TextToSpeech.SUCCESS;});}
 protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==1&&result==RESULT_OK&&data!=null){ArrayList<String> words=data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(words!=null&&!words.isEmpty()){String q=words.get(0);ask(q);}}}
 void ask(String q){String key=prefs.getString("key","");if(key.isEmpty()){status.setText("Set Gemini API key in AI Settings");return;}status.setText("Thinking...");new Thread(()->{try{org.json.JSONArray history=new org.json.JSONArray(prefs.getString("history","[]"));history.put(new org.json.JSONObject().put("role","user").put("parts",new org.json.JSONArray().put(new org.json.JSONObject().put("text",q))));java.net.HttpURLConnection c=(java.net.HttpURLConnection)new java.net.URL("https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent").openConnection();c.setConnectTimeout(20000);c.setReadTimeout(45000);c.setRequestMethod("POST");c.setRequestProperty("x-goog-api-key",key);c.setRequestProperty("Content-Type","application/json");c.setDoOutput(true);org.json.JSONObject body=new org.json.JSONObject().put("contents",history).put("systemInstruction",new org.json.JSONObject().put("parts",new org.json.JSONArray().put(new org.json.JSONObject().put("text","You are ULTRON, a helpful personal assistant. Reply in the user's language."))));try(java.io.OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes("UTF-8"));}if(c.getResponseCode()!=200)throw new Exception("Gemini HTTP "+c.getResponseCode());String raw;try(java.util.Scanner sc=new java.util.Scanner(c.getInputStream(),"UTF-8")){raw=sc.useDelimiter("\\A").next();}finally{c.disconnect();}String answer=new org.json.JSONObject(raw).getJSONArray("candidates").getJSONObject(0).getJSONObject("content").getJSONArray("parts").getJSONObject(0).getString("text");history.put(new org.json.JSONObject().put("role","model").put("parts",new org.json.JSONArray().put(new org.json.JSONObject().put("text",answer))));while(history.length()>20)history.remove(0);prefs.edit().putString("history",history.toString()).apply();runOnUiThread(()->{status.setText(answer);if(ready)tts.speak(answer,TextToSpeech.QUEUE_FLUSH,null,"reply");});}catch(Exception e){runOnUiThread(()->status.setText("AI request failed: "+e.getMessage()));}}).start();}
 protected void onDestroy(){if(tts!=null)tts.shutdown();super.onDestroy();}
}